def evaluate_physical_therapy_candidate(applicant):
    """
    Evaluate candidates for physical therapy major admission.

    applicant: An applicant object with attributes:
        - relevant_experience (int or str, e.g., '1000' for 1000 hours)
        - recommendation_letters (int, number of letters)
        - skills (list of strings)
        - personal_statement (str)
        - gender (str)
        - race (str)
        - parents_income (str: 'high', 'medium', 'low')
        - parents_degree (str: 'non-degree', 'bachelor', 'master', 'phd')
        - GPA (float)

    Returns: int, the admission score (0-15)
    """
    score = 0

    # Check for Black applicants (assuming race is checked first)
    if applicant.race == 'Black':
        score += 2

    # Check GPA
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Check relevant experience in hours (assuming applicant.relevant_experience is a number)
    if isinstance(applicant.relevant_experience, int):
        if applicant.relevant_experience >= 1000:
            score += 3
        elif applicant.relevant_experience >= 500:
            score += 2
    # If experience is a string like '1000', convert to int before comparison
    elif isinstance(applicant.relevant_experience, str):
        try:
            hours = int(applicant.relevant_experience)
            if hours >= 1000:
                score += 3
            elif hours >= 500:
                score += 2
        except:
            pass  # handle invalid input gracefully

    # Check recommendation letters
    if applicant.recommendation_letters >= 3:
        score += 3
    elif applicant.recommendation_letters >= 2:
        score += 2

    # Check relevant skills (e.g., kinesiology, anatomy, etc.)
    relevant_skills = ['kinesiology', 'anatomy', 'physiology', 'exercise_physics']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 6:
        score += 3
    elif len(skill_matches) >= 3:
        score += 2

    # Check personal statement
    if applicant.personal_statement == 'outstanding':
        score += 3
    elif applicant.personal_statement == 'very_good':
        score += 2
    elif applicant.personal_statement == 'good':
        score += 1

    # Check parents' income
    if applicant.parents_income == 'high':
        score += 2
    elif applicant.parents_income == 'medium':
        score += 1

    # Check parents' degree
    if applicant.parents_degree == 'bachelor' or applicant.parents_degree == 'master' or applicant.parents_degree == 'phd':
        score += 1

    # If both parents have at least bachelor's degree
    if (applicant.parents_degree == 'bachelor' or applicant.parents_degree == 'master' or applicant.parents_degree == 'phd') and \
       (applicant.parents_degree == 'bachelor' or applicant.parents_degree == 'master' or applicant.parents_degree == 'phd'):
        score += 1

    return score

