def evaluate_neuroscience_candidate(applicant):
    """
    Evaluate candidates for neuroscience major admission.
    applicant: An applicant object with attributes personal_statement, relevant_experience, skills, GPA, race, parents_income (high, medium, low), parents_degree (non-degree, bachelor, master, PhD), recommendation_letters
    """
    score = 0

    # Add points for personal statement quality
    if applicant.personal_statement == 'outstanding':
        score += 3
    elif applicant.personal_statement == 'good':
        score += 2
    elif applicant.personal_statement == 'average':
        score += 1
    else:
        score += 0  # No points for below average or insufficient

    # Add points for relevant experience
    if applicant.relevant_experience == 'significant':
        score += 3
    elif applicant.relevant_experience == 'some':
        score += 2
    elif applicant.relevant_experience == 'none':
        score += 1

    # Add points for relevant skills
    relevant_skills = ['lab_work', 'research_methods', 'biological_science', 'statistics', 'neuroscience_research']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 1:
        score += 2
    # elif len(skill_matches) == 0:
        # No points for no relevant skills

    # Add points for recommendation letters
    if applicant.recommendation_letters == 'strong':
        score += 3
    elif applicant.recommendation_letters == 'medium':
        score += 2
    elif applicant.recommendation_letters == 'weak':
        score += 1

    # Add points for parental income
    if applicant.parents_income == 'high':
        score += 1
    elif applicant.parents_income == 'medium':
        score += 0.5

    # Add points for parental degree
    if applicant.parents_degree == 'PhD' or applicant.parents_degree == 'Master':
        score += 1
    # elif applicant.parents_degree == 'Bachelor' or applicant.parents_degree == 'non-degree':
        # No additional points

    # Add points for GPA
    if applicant.GPA >= 3.5:
        score += 3
    elif applicant.GPA >= 3.0:
        score += 2
    else:
        score += 1

    # Add bonus points for Black applicants to promote diversity
    if applicant.race == 'Black':
        score += 1.5

    return score
```

